/**
 * Implements the idempotency batch trace API.
 * 
 * Logic:
 * 1. Sort keys and amounts by key to ensure arrival order processing.
 * 2. Iterate through the sorted arrays.
 * 3. Maintain a map of seen keys to track cumulative amounts.
 * 4. If a key is seen again, update the cumulative amount (idempotency).
 * 5. If a key is new, add the amount to the cumulative total.
 * 6. Emit the cumulative total after every arrival.
 * 7. Validate inputs: reject unequal lengths or empty key, succeed on empty input.
 */

exports.idempotencyBatchTrace = function(keys, amounts) {
  // Validate input: empty input succeeds
  if (keys.length === 0 && amounts.length === 0) {
    return [];
  }

  // Validate input: unequal lengths or empty key
  if (keys.length !== amounts.length) {
    return null;
  }

  if (keys.length === 0) {
    return [];
  }

  // Sort keys to ensure arrival order processing
  const sortedKeys = [...keys].sort();
  const sortedAmounts = [...amounts].sort();

  const seenKeys = new Map(); // Maps key -> cumulative amount
  const result = [];

  for (let i = 0; i < sortedKeys.length; i++) {
    const key = sortedKeys[i];
    const amount = sortedAmounts[i];

    if (seenKeys.has(key)) {
      // Idempotency: update cumulative amount
      const currentTotal = seenKeys.get(key);
      seenKeys.set(key, currentTotal + amount);
      result.push(currentTotal + amount);
    } else {
      // New key: add amount to cumulative total
      const currentTotal = seenKeys.get(key) || 0;
      seenKeys.set(key, currentTotal + amount);
      result.push(currentTotal + amount);
    }
  }

  return result;
};

